  (* [comment removed for export] *)
  (* [comment removed for export] *)
  (* [comment removed for export] *)
  Lemma seg_T2 : forall s msF mo regs mem (N PL cfg CP r D : word) K,
    regs158 regs N PL cfg CP -> getr regs 21 = r -> getr regs 10 = D -> (bv_unsigned D <> 0)%Z ->
    stk_ok RSEGS mem sp 128 -> aro_none mem -> arelro_none mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0x8efd4) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        regs158 regs' N PL D CP -> getr regs' 21 = r -> getr regs' 1 = Z_to_bv 64 0xbec68 ->
        getr regs' 10 = D -> getr regs' 11 = PL -> getr regs' 12 = N ->
        (forall r : reg, In r [22; 23; 24; 25; 26; 27]%list -> getr regs' r = getr regs r) ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbec54) mem rom -> as_AKREL H s (mkCfg msF mo) ->
