  Lemma seg_T3 : forall s msF mo regs mem (N PL CP r D : word) K,
    regs158 regs N PL D CP -> getr regs 21 = r ->
    stk_ok RSEGS mem sp 128 -> aro_none mem -> arelro_none mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xbeca8) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        loop_base regs' N D D -> getr regs' 21 = r -> getr regs' 19 = CP ->
        keep4 regs regs' ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbec68) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes asegs (mkCfg msF mo) K.
