  Lemma seg_T6 : forall s msF mo regs mem (N D OW r : word) K,
    loop_base regs N D OW -> getr regs 21 = r -> getr regs 10 = Z_to_bv 64 0 ->
    stk_ok RSEGS mem sp 128 -> aro_none mem -> arelro_none mem ->
    (forall regs' mem' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xbed78) mem' rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        loop_base regs' N D OW -> getr regs' 19 = Z_to_bv 64 0 -> getr regs' 21 = r -> getr regs' 1 = Z_to_bv 64 0xbeccc ->
        getr regs' 11 = Z_to_bv 64 0 ->
        keep4 regs regs' -> frame_mod mem mem' regT5_w -> stk_ok RSEGS mem' sp 128 ->
        rdn RSEGS mem' (Z_to_bv 64 0x6f2894) 1 = Some (word_to_le_bytes 1 (Z_to_bv 64 0)) ->
        (forall a : word, a <> Z_to_bv 64 0x6f2894 -> mem' a = mem a) ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbecbc) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes asegs (mkCfg msF mo) K.
